import {destinations,byId,interests,regions,visitedCount,tourismLabels} from './data.js';
import {emptyFilters,filterDestinations,visitLabel} from './explorer-model.js';
import {bangkokGuide,groupBudget,checkNewYear} from './bangkok.js';
import {loadMap,baseMap,project} from './map-view.js';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=Object.fromEntries(interests.map(([k,l])=>[k,l]));
const badge=d=>`<span class="visit-badge ${d.visitedByMax===true?'visited':d.visitedByMax===false?'not-visited':'unknown'}">${d.visitedByMax===true?'✳':'◇'} ${visitLabel(d)}</span>`;
const tourism=d=>d.tourismLevel==null?'<span class="tourism-unknown">Noch nicht eingestuft</span>':`<span class="tourism-indicator" aria-label="Tourismusgrad ${d.tourismLevel} von 5: ${esc(d.tourismDescription)}">${Array.from({length:5},(_,i)=>`<i class="${i<d.tourismLevel?'filled':''}"></i>`).join('')}<strong>${d.tourismLevel}/5</strong></span>`;
const tags=d=>`<div class="interest-tags">${d.categories.map(k=>`<span class="interest-tag">${esc(label[k])}</span>`).join('')}</div>`;
const list=items=>`<ul>${items.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`;
const cards=items=>`<div class="guide-info-grid">${items.map(i=>`<article><h4>${esc(i.title||i.name)}</h4><p>${esc(i.text||i.summary||'')}</p></article>`).join('')}</div>`;
const art=d=>`<img src="${d.images[0].src}" alt="${esc(d.images[0].alt)}" width="800" height="480" loading="lazy"><span class="art-caption">Illustration · kein Ortsfoto</span>`;
let filters=emptyFilters(),filtered=[],compared=[],mapData=null,mapZoom=1,mapCenter=[360,255],mapGroups=[],mapSelection=[],currentView='explorer',detailId=null,onAdd,onToast;
try{const saved=JSON.parse(localStorage.getItem('sabai-compare-v1'));if(Array.isArray(saved))compared=[...new Set(saved.filter(id=>byId[id]))].slice(0,4);}catch{}
function rememberCompare(){try{localStorage.setItem('sabai-compare-v1',JSON.stringify(compared));}catch{}}
function setUrl(hash){if(globalThis.location?.hash!==hash)globalThis.history?.pushState(null,'',hash);}
function showView(view,updateUrl=true){
 currentView=view;const isExplorer=view==='explorer'||view==='guide';$('explorer').hidden=!isExplorer;$('planner').hidden=view!=='planner';$('destination-detail').hidden=view!=='detail';
 for(const key of ['explorer','guide','planner']){$('nav-'+key).classList.toggle('active',key===view);$('nav-'+key).setAttribute('aria-pressed',key===view);}
 if(isExplorer){if(view==='guide')filters.visited='visited';$('visit-filter').value=filters.visited;$('explorer-eyebrow').textContent=view==='guide'?'PERSÖNLICH BEREIST. FÜR DICH ENTDECKBAR.':'DEIN NÄCHSTER LIEBLINGSORT WARTET';$('explorer-title').textContent=view==='guide'?'Max’ Thailand Guide':'Eine Reise beginnt mit Neugier.';$('explorer-description').textContent=view==='guide'?`${visitedCount} von Max bereiste Destinationen. Das Kennzeichen bestätigt den Besuch am Ort; einzelne Angebote sind allgemeine Reiseinformationen.`:'Entdecke Thailand, vergleiche deine Favoriten und bring sie auf deine Route.';renderExplorer();}
 if(updateUrl)setUrl(view==='guide'?'#max-guide':view==='planner'?'#planner':'#explorer');
}
function renderFilters(){
 $('region-filter').innerHTML='<option value="all">Alle Regionen</option>'+regions.map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('');
 $('explorer-search').value=filters.query;$('visit-filter').value=filters.visited;$('region-filter').value=filters.region;$('sort-filter').value=filters.sort;$('tourism-min').value=filters.tourismMin;$('tourism-max').value=filters.tourismMax;$('category-all').checked=filters.categoryMode==='all';renderChips();
}
function renderChips(){$('category-chips').innerHTML=interests.map(([k,l,i])=>`<button class="category-chip ${filters.categories.includes(k)?'active':''}" data-category="${k}" aria-pressed="${filters.categories.includes(k)}"><span aria-hidden="true">${i}</span> ${l}</button>`).join('');}
function renderExplorer(){
 filtered=filterDestinations(filters);$('tourism-output').textContent=filters.tourismMin+'–'+filters.tourismMax;
 const unknown=filtered.filter(d=>d.visitedByMax==null).length;
 $('explorer-count').textContent=`${filtered.length} von ${destinations.length} Destinationen${unknown?' · '+unknown+' mit unbekanntem Besuchsstatus':''}${filters.tourismMin!==1||filters.tourismMax!==5?' · Ziele ohne Tourismusbewertung ausgeblendet':''}`;
 $('destination-grid').innerHTML=filtered.map(d=>`<article class="destination-card" data-destination-card="${d.id}"><div class="destination-art">${art(d)}${d.destinationType==='dayTrip'?'<span class="trip-type">Tagesausflug</span>':''}</div><div class="destination-card-body"><div class="destination-meta">${esc(d.region)}</div><h3><button data-open-destination="${d.id}">${esc(d.name)}</button></h3>${badge(d)}<div class="card-tourism">${tourism(d)}<span>Tourismus</span></div><p class="card-description">${esc(d.shortDescription)}</p>${tags(d)}<div class="card-actions"><button class="secondary" data-open-destination="${d.id}">Details ↗</button><button class="text-button" data-add-destination="${d.id}" ${d.destinationType==='dayTrip'?'data-as-daytrip="true"':''}>＋ Zum Trip</button></div><label class="compare-checkbox"><input type="checkbox" data-compare="${d.id}" ${compared.includes(d.id)?'checked':''}> Vergleichen</label></div></article>`).join('');
 $('explorer-empty').hidden=filtered.length>0;renderCompareTray();mapSelection=mapSelection.filter(id=>filtered.some(d=>d.id===id));renderMap();
}
function renderCompareTray(){$('compare-tray').hidden=!compared.length;$('compare-count').textContent=`${compared.length} von 4 Zielen ausgewählt`;$('open-compare').disabled=compared.length<2;}
function toggleCompare(id,checked){if(checked&&!compared.includes(id)&&compared.length>=4){document.querySelectorAll('[data-compare="'+id+'"]').forEach(el=>el.checked=false);onToast('Du kannst bis zu vier Ziele miteinander vergleichen.');return;}compared=checked?[...new Set([...compared,id])]:compared.filter(x=>x!==id);rememberCompare();document.querySelectorAll('[data-compare="'+id+'"]').forEach(el=>el.checked=compared.includes(id));renderCompareTray();}
function compare(){
 const ds=compared.map(id=>byId[id]);if(ds.length<2)return;
 const rows=[['Besuchsstatus',d=>badge(d)],['Region',d=>esc(d.region)+'<br><small>'+esc(d.province)+'</small>'],['Tourismus (redaktionell)',d=>tourism(d)+'<p>'+esc(d.tourismDescription)+'</p>'],['Charakter',d=>esc(d.character)],['Kategorien',d=>tags(d)],['Aufenthalt',d=>d.overnightAllowed?`${d.recommendedStay.minNights}–${d.recommendedStay.maxNights} Nächte · Planungsannahme`:'Tagesausflug · keine Übernachtungsbasis'],['Highlights',d=>list(d.highlights)],['Nachteile',d=>list(d.downsides)],['Planung',d=>list(d.planningNotes)],['Max’ persönliche Notiz',d=>d.personalNote?esc(d.personalNote):'Noch nicht ergänzt']];
 $('compare-content').innerHTML=`<p class="guide-disclaimer">Tourismuswerte sind subjektive Einschätzungen für die Hauptsaison. Ein Besuchskennzeichen bestätigt keine persönliche Erfahrung mit allen genannten Angeboten.</p><div class="compare-scroll" tabindex="0" role="region" aria-label="Reisezielvergleich horizontal scrollbar"><table><thead><tr><th scope="col">Dein Vergleich</th>${ds.map(d=>`<th scope="col">${esc(d.name)}<button class="text-button" data-open-destination="${d.id}">Details ↗</button></th>`).join('')}</tr></thead><tbody>${rows.map(([name,fn])=>`<tr><th scope="row">${name}</th>${ds.map(d=>`<td>${fn(d)}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Dein Reiseplan</th>${ds.map(d=>`<td><button class="secondary" data-add-destination="${d.id}" ${d.destinationType==='dayTrip'?'data-as-daytrip="true"':''}>＋ Zum Trip hinzufügen</button></td>`).join('')}</tr></tbody></table></div>`;
 $('compare-dialog').showModal();
}
function renderMap(){
 mapGroups=[];for(const d of filtered){const p=project([d.lon,d.lat]);const group=mapGroups.find(g=>Math.hypot(g.x-p[0],g.y-p[1])*mapZoom<21);if(group)group.destinations.push(d);else mapGroups.push({x:p[0],y:p[1],destinations:[d]});}
 $('explorer-map').innerHTML=`<g transform="translate(${360-mapCenter[0]*mapZoom} ${255-mapCenter[1]*mapZoom}) scale(${mapZoom})">${baseMap(mapData)}<text class="country-label thai" x="414" y="220">THAILAND</text>${mapGroups.map((g,i)=>{const allVisited=g.destinations.every(d=>d.visitedByMax===true),someVisited=g.destinations.some(d=>d.visitedByMax===true);return `<g class="explorer-marker ${allVisited?'visited':someVisited?'mixed':'unknown'}" role="button" tabindex="0" data-map-group="${i}" aria-label="${esc(g.destinations.map(d=>d.name+': '+visitLabel(d)).join('; '))}. Auswahl öffnen"><title>${esc(g.destinations.map(d=>d.name).join(', '))}</title><circle class="hit-target" cx="${g.x}" cy="${g.y}" r="${28/mapZoom}"/><circle class="marker-face" cx="${g.x}" cy="${g.y}" r="${(g.destinations.length>1?15:11)/mapZoom}" stroke-width="${2/mapZoom}"/>${g.destinations.length>1?`<text x="${g.x}" y="${g.y}" font-size="${11/mapZoom}">${g.destinations.length}</text>`:`<circle class="marker-core" cx="${g.x}" cy="${g.y}" r="${3/mapZoom}"/>`}</g>`;}).join('')}</g>`;
 renderPopup();
}
function renderPopup(){$('map-popup').hidden=!mapSelection.length;$('map-popup').innerHTML=mapSelection.map(id=>{const d=byId[id];return `<article><div><h4>${esc(d.name)}</h4>${badge(d)}<p>${esc(d.region)} · ${d.tourismLevel==null?'Tourismusgrad offen':d.tourismLevel+'/5 Tourismus'}</p></div><div class="map-popup-actions"><button class="text-button" data-open-destination="${id}">Details ↗</button><button class="secondary" data-add-destination="${id}" ${d.destinationType==='dayTrip'?'data-as-daytrip="true"':''}>＋ Zum Trip</button></div></article>`;}).join('');}
function bangkokSections(){const g=bangkokGuide,nye=g.seasonalEvents[0];return `
 <nav class="detail-section-nav" aria-label="Bangkok-Guide Abschnitte">${[['discover','Bangkok entdecken'],['areas','Stadtviertel & Hotellagen'],['hotels','Hotel- & Gruppenlogistik'],['transport','Flughäfen & Transport'],['culture','Kultur'],['food','Streetfood & Märkte'],['nightlife','Rooftops & Nachtleben'],['newyear','Silvester'],['unusual','Außergewöhnliches']].map(([id,t])=>`<a href="#bkk-${id}" data-section-link="bkk-${id}">${t}</a>`).join('')}</nav>
 <section id="bkk-discover" class="guide-section"><div class="eyebrow">DIE STADT HAT VIELE SEITEN</div><h3>Bangkok entdecken</h3><p>Eine Metropole für Kultur, kulinarische Entdeckungen und außergewöhnliche Abende – auch wenn du schon einmal hier warst. Bündle deine Erlebnisse nach Vierteln.</p>${cards(g.urbanAreas)}</section>
 <section id="bkk-areas" class="guide-section"><div class="eyebrow">EINE GUTE BASIS MACHT DEN UNTERSCHIED</div><h3>${g.accommodationAdvice.title}</h3>${list(g.accommodationAdvice.principles)}<h4>Der Hotel-Lageberater</h4><label class="area-selector">Was ist dir bei deiner Basis wichtig?<select id="hotel-area-select"><option value="all">Alle Gegenden vergleichen</option>${g.recommendedAreas.map(a=>`<option value="${a.id}">${a.for}</option>`).join('')}</select></label><div id="hotel-area-cards">${areaCards('all')}</div></section>
 <section id="bkk-hotels" class="guide-section"><h3>Hotel- & Gruppenlogistik</h3><details open><summary>Hotelbeispiele aus Max’ Reiseplanung <span>＋</span></summary><div class="hotel-examples">${g.accommodationAdvice.planningHotels.map(h=>`<article><h4>${esc(h.name)}</h4>${h.address?`<p>${esc(h.address)}</p>`:''}${h.context?`<p>${esc(h.context)}</p>`:''}</article>`).join('')}</div><p class="guide-disclaimer">${g.accommodationAdvice.caveat}</p></details><h4>${g.groupTravelTips.title}</h4>${list(g.groupTravelTips.tips)}<details><summary>Historisches Gruppen- und Budgetbeispiel <span>＋</span></summary><p>${g.groupTravelTips.example}</p></details><div class="budget-calculator"><h4>Eure Zimmerplanung durchrechnen</h4><p>Eigene Preisannahmen eingeben. Beträge gelten pro Zimmer und Nacht; es werden keine Hotelpreise abgerufen.</p><div class="budget-inputs"><label>Eigene Einzelzimmer<input id="budget-singles" type="number" min="0" max="100" value="4"></label><label>Paare · je ein Doppelzimmer<input id="budget-couples" type="number" min="0" max="100" value="2"></label><label>Nächte<input id="budget-nights" type="number" min="1" max="60" value="2"></label><label>Einzelzimmer €/Nacht<input id="budget-single-rate" type="number" min="0" step="0.01" placeholder="Eigene Annahme"></label><label>Doppelzimmer €/Nacht<input id="budget-double-rate" type="number" min="0" step="0.01" placeholder="Eigene Annahme"></label></div><div id="budget-result" role="status" aria-live="polite">Trage eure eigenen Preisannahmen ein.</div></div></section>
 <section id="bkk-transport" class="guide-section"><h3>Flughäfen & Transport</h3><p>BKK und DMK sind verschiedene Flughäfen mit unterschiedlichen Anreisewegen. Richte die Planung immer nach dem tatsächlich gebuchten Flughafen und dem konkreten Hotel aus.</p>${cards(g.airportConnections.map(a=>({title:a.code+' · '+a.name,text:a.summary+' '+a.caveat})))}<h4>Innerhalb Bangkoks</h4>${cards(g.transportTips)}${list(g.logisticsRules)}</section>
 <section id="bkk-culture" class="guide-section"><h3>Kultur und Sehenswürdigkeiten</h3><p>Klassisches Sightseeing: Grand Palace, Wat Pho, Wat Arun, Chao Phraya River, Chinatown / Yaowarat und Chatuchak Weekend Market. Öffnungszeiten, Besuchsregeln und Zugänge aktuell prüfen.</p></section>
 <section id="bkk-food" class="guide-section"><h3>Streetfood und Märkte</h3>${list(g.foodAreas)}<p>Mehrere Essensstopps in einem Viertel lassen sich gut verbinden. Aktuelle Markttage und die Öffnung konkreter Stände prüfen.</p></section>
 <section id="bkk-nightlife" class="guide-section"><h3>Rooftops und Nachtleben</h3>${list(g.nightlifeAreas)}<p class="guide-disclaimer">${g.activityCaveat}</p></section>
 <section id="bkk-newyear" class="guide-section newyear-section"><div class="eyebrow">GUT GEPLANT INS NEUE JAHR</div><h3>${nye.title}</h3><p>${nye.intro}</p><details open><summary>Chao Phraya & mögliche Aussichtspunkte <span>＋</span></summary>${list(nye.orientation)}<div class="guide-note"><strong>${nye.discussedSpot.name}</strong><p>${nye.discussedSpot.address}</p><p>${nye.discussedSpot.context}</p></div></details><details><summary>Rooftop-Bar: Vor der Reservierung prüfen <span>＋</span></summary>${list(nye.rooftopChecklist)}<p>${nye.rooftopNote}</p></details><h4>Logistik für den Abend</h4>${list(nye.logistics)}<div class="newyear-checker"><h4>Deinen Silvesterplan durchgehen</h4><p>${nye.liveStatus}</p><form id="newyear-form"><div class="budget-inputs"><label>Jahr<input type="number" id="nye-year" min="2026" max="2100" value="${new Date().getFullYear()}"></label><label>Hotelgegend<select id="nye-hotel"><option value="">Noch offen</option>${g.recommendedAreas.map(a=>`<option value="${a.id}">${a.name}</option>`).join('')}</select></label><label>Veranstaltungsgegend<select id="nye-event"><option value="">Noch offen</option>${g.recommendedAreas.map(a=>`<option value="${a.id}">${a.name}</option>`).join('')}</select></label><label>Veranstaltung / Location<input id="nye-venue" type="text" maxlength="120" placeholder="Zum Beispiel River City · zu prüfen"></label><label>Geplanter Rückweg<select id="nye-return"><option value="public">Öffentliche Verkehrsmittel</option><option value="walk">Zu Fuß</option><option value="taxi">Taxi / Fahrdienst</option></select></label></div><button type="submit" class="primary">Planungshinweise anzeigen ↗</button></form><div id="nye-result" role="status" aria-live="polite"></div></div></section>
 <section id="bkk-unusual" class="guide-section"><div class="eyebrow">BANGKOK KANN AUCH ANDERS</div><h3>Bangkok abseits des Standard-Sightseeings</h3>${list(g.unusualExperiences)}<p>${g.activityCaveat}</p></section>`;}
function areaCards(id){return `<div class="hotel-area-grid">${bangkokGuide.recommendedAreas.filter(a=>id==='all'||a.id===id).map(a=>`<article><h4>${a.name}</h4><p><strong>Passend für:</strong> ${a.for}</p><div class="area-pros">${list(a.pros)}</div><div class="area-cons">${list(a.cons)}</div>${a.landmarks?`<details><summary>Orientierungspunkte <span>＋</span></summary>${list(a.landmarks)}<p>${a.context}</p></details>`:''}</article>`).join('')}</div>`;}
function openDetail(id,updateUrl=true){
 const d=byId[id];if(!d)return;detailId=id;if($('compare-dialog').open)$('compare-dialog').close();showView('detail',false);
 $('destination-detail').innerHTML=`<button class="text-button back-to-explorer" data-main-view="${filters.visited==='visited'?'guide':'explorer'}">← Zurück zu den Reisezielen</button><div class="detail-hero"><div class="detail-hero-art">${art(d)}</div><div class="detail-hero-content"><div class="eyebrow">${esc(d.region)} · ${esc(d.province)}</div><h2 id="destination-title" tabindex="-1">${esc(d.name)}</h2>${badge(d)}${d.visitContext?`<p class="visit-context">${esc(d.visitContext)}</p>`:''}<p>${esc(d.character)}</p><div class="detail-tourism">${tourism(d)}<span>${esc(d.tourismDescription)}</span></div><div class="detail-actions"><button class="primary" data-add-destination="${id}" ${!d.overnightAllowed?'data-as-daytrip="true"':''}>＋ ${d.overnightAllowed?'Zum Trip hinzufügen':'Als Tagesausflug hinzufügen'}</button>${d.overnightAllowed&&d.dayTripFrom.length?`<button class="secondary" data-add-destination="${id}" data-as-daytrip="true">Als Tagesausflug ab Krabi</button>`:''}<label class="compare-checkbox"><input type="checkbox" data-compare="${id}" ${compared.includes(id)?'checked':''}> Vergleichen</label><button class="text-button" data-compare-open>Vergleich öffnen ↗</button></div></div></div>
 <div class="detail-overview"><section><h3>Bekannt für</h3><p>${esc(d.shortDescription)}</p>${tags(d)}</section><aside class="detail-facts"><h3>Gut einzuordnen</h3><p><strong>${d.overnightAllowed?`${d.recommendedStay.minNights}–${d.recommendedStay.maxNights} Nächte`:'Tagesausflug ohne Übernachtung'}</strong>${d.overnightAllowed?' · redaktionelle Planungsannahme':''}</p><p>Tourismuswerte: subjektive Klassifizierung für die Hauptsaison, keine offiziellen Besucherzahlen.</p><p>Das Besuchskennzeichen gilt ausschließlich für die Destination. Erwähnte Hotels, Restaurants und Aktivitäten sind dadurch nicht als persönlich getestet bestätigt.</p></aside></div>
 <div class="detail-info-grid"><section class="guide-section"><h3>Highlights & Sehenswürdigkeiten</h3>${d.highlights.length?list(d.highlights):'<p>Weitere redaktionelle Highlights folgen. Die bisherigen Erlebnisvorschläge bleiben im Trip Planner verfügbar.</p>'}</section><section class="guide-section"><h3>Besonderheiten & Charakter</h3>${list(d.specialFeatures)}<h4>Was du bedenken solltest</h4>${d.downsides.length?list(d.downsides):'<p>Zusätzliche redaktionelle Einschätzungen sind noch offen.</p>'}</section></div>
 <section class="guide-section"><h3>Planung & Logistik</h3>${list(d.planningNotes)}<p>Transportoptionen, Saison, Wetter und tatsächliche Zugänglichkeit vor Buchung prüfen. Die Empfehlungen enthalten keine verifizierten Fahrpläne oder Reisezeiten.</p>${d.nearbyDestinations.length?`<h4>Geografisch passende Anschlussideen</h4><div class="nearby-links">${d.nearbyDestinations.map(id=>`<button class="secondary" data-open-destination="${id}">${esc(byId[id]?.name||id)} ↗</button>`).join('')}</div><p class="guide-disclaimer">Geografische Anschlussidee bedeutet keine bestätigte direkte Verkehrsverbindung.</p>`:''}</section>
 <section class="guide-section personal-note"><h3>Max’ persönliche Erfahrungsnotiz</h3><p>${d.personalNote?esc(d.personalNote):'Für dieses Ziel wurde noch keine persönliche Notiz ergänzt.'}</p>${d.personalRating!=null?`<p>Max’ Bewertung: ${esc(d.personalRating)}/5</p>`:''}</section>
 ${id==='bangkok'?bangkokSections():''}
 <details class="source-details"><summary>Quellen, Einordnung & Bildrechte <span>＋</span></summary><p>Inhalte und Besuchsstatus: redaktioneller Auftrag von Max. Persönliche Details über Mitreisende werden nicht veröffentlicht.</p><p>Koordinaten: <a href="${esc(d.coordinateSource.url)}" target="_blank" rel="noopener noreferrer">Geografische Referenz ↗</a> · geprüft ${esc(d.coordinateSource.checkedAt)}. ${esc(d.coordinateSource.scope)}</p><p>${d.images[0].credit} · ${d.images[0].license}. Die Darstellung ist eine eigene stilisierte Illustration.</p></details>`;
 if(updateUrl)setUrl('#destination/'+id);$('destination-title').focus({preventScroll:true});$('destination-detail').scrollIntoView?.({block:'start',behavior:'instant'});
 if(id==='bangkok')bindBangkok();
}
function bindBangkok(){
 $('hotel-area-select').addEventListener('change',()=>$('hotel-area-cards').innerHTML=areaCards($('hotel-area-select').value));
 for(const id of ['budget-singles','budget-couples','budget-nights','budget-single-rate','budget-double-rate'])$(id).addEventListener('input',()=>{
  const ids=['budget-singles','budget-couples','budget-nights','budget-single-rate','budget-double-rate'];if(ids.some(id=>$(id).value==='')){$('budget-result').textContent='Trage Zimmeranzahl, Nächte und eure eigenen Preisannahmen ein.';return;}
  const budget=groupBudget(Object.fromEntries(['singles','couples','nights','singleRate','doubleRate'].map((k,i)=>[k,Number($(ids[i]).value)])));
  const euro=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n);
  $('budget-result').textContent=budget?`${budget.people} Personen · ${budget.rooms} Zimmer · gesamt ${euro(budget.total)}. Pro Person im eigenen Einzelzimmer: ${euro(budget.singlePerPerson)}; im geteilten Doppelzimmer: ${euro(budget.couplePerPerson)}. Eigene Annahme, ohne weitere Gebühren.`:'Bitte gültige, nicht negative Werte und mindestens eine Personengruppe eingeben.';
 });
 $('newyear-form').addEventListener('submit',e=>{e.preventDefault();const r=checkNewYear({hotelArea:$('nye-hotel').value,eventArea:$('nye-event').value,returnMode:$('nye-return').value,venue:$('nye-venue').value.trim(),year:$('nye-year').value});$('nye-result').innerHTML=`<div class="guide-note"><h4>Deine Planungsprüfung · Silvester ${esc(r.year)}</h4><p><strong>Hotel:</strong> ${esc(r.hotel)}<br><strong>Abend:</strong> ${esc(r.event)}<br><strong>Location:</strong> ${esc(r.venue)}</p><p>${r.sameArea?'Hotel und Veranstaltung liegen in derselben groben Gegend. Konkrete Distanz und Fußroute sind noch zu prüfen.':'Die Gegenden sind unterschiedlich oder noch nicht vollständig gewählt. Den Hin- und Rückweg separat planen.'}</p><p>${r.transport}</p>${list(r.checks)}<p><strong>Aktueller Datenstatus:</strong> Keine geprüften Straßensperren, Veranstaltung, Sichtachse oder Sonderfahrpläne. Noch keine bestätigte Rückfahrt.</p></div>`;});
}
function routeFromHash(){const hash=globalThis.location?.hash||'';if(hash.startsWith('#destination/')){const id=hash.slice(13);if(byId[id])openDetail(id,false);else showView('explorer',false);}else if(hash==='#planner'||hash.startsWith('#trip/'))showView('planner',false);else if(hash==='#max-guide')showView('guide',false);else showView('explorer',false);}
export function initExplorer({addToTrip,toast}){
 onAdd=addToTrip;onToast=toast;renderFilters();showView('explorer',false);routeFromHash();
 document.addEventListener('click',e=>{
  const nav=e.target.closest('[data-main-view]');if(nav){e.preventDefault();const view=nav.dataset.mainView;if(view==='explorer')filters.visited='all';showView(view);return;}
  const open=e.target.closest('[data-open-destination]');if(open){e.preventDefault();openDetail(open.dataset.openDestination);return;}
  const add=e.target.closest('[data-add-destination]');if(add){if(onAdd(add.dataset.addDestination,{asDayTrip:add.dataset.asDaytrip==='true'})){if($('compare-dialog').open)$('compare-dialog').close();showView('planner');$('planner').scrollIntoView?.({block:'start'});}return;}
  const section=e.target.closest('[data-section-link]');if(section){e.preventDefault();$(section.dataset.sectionLink)?.scrollIntoView?.({behavior:'smooth',block:'start'});return;}
  if(e.target.closest('[data-compare-open]')){if(compared.length<2)onToast('Wähle mindestens zwei Ziele für deinen Vergleich aus.');else compare();}
 });
 document.addEventListener('change',e=>{const el=e.target.closest('[data-compare]');if(el)toggleCompare(el.dataset.compare,el.checked);});
 const update=()=>{filters.query=$('explorer-search').value;filters.visited=$('visit-filter').value;filters.region=$('region-filter').value;filters.sort=$('sort-filter').value;filters.categoryMode=$('category-all').checked?'all':'any';renderExplorer();};
 for(const id of ['visit-filter','region-filter','sort-filter','category-all'])$(id).addEventListener('change',update);$('explorer-search').addEventListener('input',update);
 for(const id of ['tourism-min','tourism-max'])$(id).addEventListener('input',()=>{let min=Number($('tourism-min').value),max=Number($('tourism-max').value);if(min>max){if(id==='tourism-min')max=min;else min=max;}$('tourism-min').value=min;$('tourism-max').value=max;filters.tourismMin=min;filters.tourismMax=max;renderExplorer();});
 $('category-chips').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;const key=b.dataset.category;filters.categories=filters.categories.includes(key)?filters.categories.filter(k=>k!==key):[...filters.categories,key];renderChips();renderExplorer();});
 $('reset-filters').addEventListener('click',()=>{filters=emptyFilters();if(currentView==='guide')filters.visited='visited';renderFilters();renderExplorer();});
 $('clear-compare').addEventListener('click',()=>{compared=[];rememberCompare();renderExplorer();if(detailId&&currentView==='detail')openDetail(detailId,false);});$('open-compare').addEventListener('click',compare);
 const mapSelect=e=>{const marker=e.target.closest('[data-map-group]');if(marker){const group=mapGroups[Number(marker.dataset.mapGroup)];mapSelection=group.destinations.map(d=>d.id);renderPopup();}};
 $('explorer-map').addEventListener('click',mapSelect);$('explorer-map').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();mapSelect(e);}});
 $('explore-map-plus').addEventListener('click',()=>{mapZoom=Math.min(4,mapZoom+.5);if(mapSelection.length){const d=byId[mapSelection[0]];mapCenter=project([d.lon,d.lat]);}renderMap();});$('explore-map-minus').addEventListener('click',()=>{mapZoom=Math.max(1,mapZoom-.5);renderMap();});$('explore-map-reset').addEventListener('click',()=>{mapZoom=1;mapCenter=[360,255];renderMap();});
 globalThis.addEventListener?.('popstate',routeFromHash);globalThis.addEventListener?.('hashchange',routeFromHash);
 loadMap().then(data=>{mapData=data;renderMap();}).catch(()=>onToast('Länderumrisse sind nicht verfügbar. Die gefilterten Ortsmarker bleiben sichtbar.'));
 return {showView,openDetail};
}
